#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricCurrentGradient; 7] = [
        ElectricCurrentGradient::const_new(1234.5, ElectricCurrentGradientUnit::AmperePerSecond),
        ElectricCurrentGradient::const_new(
            1234.5,
            ElectricCurrentGradientUnit::MilliamperePerSecond,
        ),
        ElectricCurrentGradient::const_new(1234.5, ElectricCurrentGradientUnit::AmperePerMinute),
        ElectricCurrentGradient::const_new(
            1234.5,
            ElectricCurrentGradientUnit::MilliamperePerMinute,
        ),
        ElectricCurrentGradient::const_new(
            1234.5,
            ElectricCurrentGradientUnit::AmperePerMillisecond,
        ),
        ElectricCurrentGradient::const_new(
            1234.5,
            ElectricCurrentGradientUnit::AmperePerMicrosecond,
        ),
        ElectricCurrentGradient::const_new(
            1234.5,
            ElectricCurrentGradientUnit::AmperePerNanosecond,
        ),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricCurrentGradientUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricCurrentGradient::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricCurrentGradientUnit::ALL {
            assert_eq!(
                ElectricCurrentGradient::const_new(v, unit)
                    .as_base()
                    .to_bits(),
                ElectricCurrentGradient::<f64>::new(v, unit)
                    .as_base()
                    .to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricCurrentGradient::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricCurrentGradient::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricCurrentGradientUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricCurrentGradient::from_base(0.0).auto_unit().unit,
        ElectricCurrentGradientUnit::AmperePerSecond
    );
}

